#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $root = '/bench/repo';

# symbol_id => { pkgpath, pkg, recv, name, file, line, exported }
my %defs;
# file => { pkgpath, pkg, imports => { alias => pkgpath } }
my %files;

sub pkgpath_from_file {
    my ($f) = @_;
    return undef unless $f =~ m{/internal/};
    my ($pp) = $f =~ m{($root/internal/[^/]+(?:/[^/]+)*)};
    $pp =~ s{^$root/}{};
    return $pp;
}

sub read_file {
    my ($f) = @_;
    open my $fh, '<', $f or return '';
    local $/; my $c = <$fh>; close $fh;
    return $c;
}

sub parse_imports {
    my ($content, $pkgpath) = @_;
    my %imports;
    while ($content =~ /^\s*import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg) {
        my $block = defined $1 ? $1 : qq{"$2"};
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $alias = $1 if !$alias && $path =~ m{/([^/]+)$};
            $imports{$alias} = $path;
        }
    }
    return %imports;
}

sub strip_comments {
    my ($c) = @_;
    $c =~ s{//[^\n]*}{}g;
    $c =~ s{/\*.*?\*/}{}gs;
    return $c;
}

# Collect all Go files and metadata
find({
    wanted => sub {
        return unless /\.go$/;
        my $f = $File::Find::name;
        my $content = read_file($f);
        my ($pkg) = $content =~ /^package\s+(\w+)/m;
        return unless $pkg;
        my $pp = pkgpath_from_file($f);
        my %imports = parse_imports($content, $pp);
        $files{$f} = { pkg => $pkg, pkgpath => $pp, imports => \%imports, content => $content };

        return unless defined $pp; # only defs under internal/

        my $line = 0;
        for my $raw (split /\n/, $content) {
            $line++;
            next if $raw =~ /^\s*\/\//;
            if ($raw =~ /^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($1, $2);
            $recv =~ s/^\*//;
            $recv =~ s/^\w+\s+//;
            $recv =~ s/\s+//g;
            my $id = "$pp|$recv|$name";
            $defs{$id} = {
                pkgpath => $pp, pkg => $pkg, recv => $recv, name => $name,
                file => $f, line => $line, exported => ($name =~ /^[A-Z]/)
            };
            } elsif ($raw =~ /^func\s+(\w+)\s*\(/) {
            my $name = $1;
            my $id = "$pp||$name";
            $defs{$id} = {
                pkgpath => $pp, pkg => $pkg, recv => '', name => $name,
                file => $f, line => $line, exported => ($name =~ /^[A-Z]/)
            };
            }
        }
    },
    no_chdir => 1,
}, $root);

# Resolve import alias for a pkgpath in a file
sub resolve_aliases {
    my ($fmeta, $target_pp) = @_;
    my @aliases;
    my $pkg = (split m{/}, $target_pp)[-1];
    push @aliases, $pkg;
    for my $alias (keys %{$fmeta->{imports}}) {
        my $path = $fmeta->{imports}{$alias};
        $path =~ s{^github\.com/usememos/memos/}{};
        push @aliases, $alias if $path eq $target_pp;
    }
    return @aliases;
}

# Count call sites per symbol
my %call_sites;
my %callers; # symbol_id => { caller_id => 1 }

for my $f (keys %files) {
    my $meta = $files{$f};
    my $content = strip_comments($meta->{content});
    my $caller_pkgpath = $meta->{pkgpath} // '';
    my $caller_pkg = $meta->{pkg};

    for my $id (keys %defs) {
        my $d = $defs{$id};
        my $name = $d->{name};
        my $pp = $d->{pkgpath};
        my $recv = $d->{recv};

        my @patterns;
        if ($recv eq '') {
            # package-level function
            if ($caller_pkgpath eq $pp) {
                push @patterns, qr/\b\Q$name\E\s*\(/;
            }
            if ($d->{exported}) {
                for my $alias (resolve_aliases($meta, $pp)) {
                    push @patterns, qr/\b\Q$alias\E\.\Q$name\E\s*\(/;
                }
            }
        } else {
            # method: match .MethodName( — static over-approximation
            push @patterns, qr/\.\Q$name\E\s*\(/;
        }

        my $count = 0;
        for my $pat (@patterns) {
            while ($content =~ /$pat/g) {
                $count++;
            }
        }

        # For methods, filter: if multiple methods share name in internal, we over-count.
        # Refine: only count if file could plausibly call this — skip for now, note limitation.

        if ($count > 0) {
            $call_sites{$id} += $count;
            # rough caller: whole file as one unit (we'll refine)
            $callers{$id}{$f} = 1;
        }
    }
}

# For methods with duplicate names across packages, the .MethodName( pattern over-counts
# within files that don't use that type. Re-count methods more carefully using receiver-qualified patterns where possible.

# Re-run method counting with package context for exported methods on named types
for my $id (keys %defs) {
    my $d = $defs{$id};
    next unless $d->{recv} ne '';

    my $name = $d->{name};
    my $pp = $d->{pkgpath};
    my $recv = $d->{recv};

    # Only re-count if there are competing methods with same name in internal
    my $competitors = 0;
    for (values %defs) {
        $competitors++ if $_->{name} eq $name && $_->{recv} ne '';
    }
    next if $competitors <= 3; # skip refinement for low ambiguity

    my $total = 0;
    my %caller_files;
    for my $f (keys %files) {
        my $meta = $files{$f};
        my $content = strip_comments($meta->{content});
        my @aliases = resolve_aliases($meta, $pp);
        my $count = 0;

        # Type-based: alias.RecvVar.Method( or &Type{}.Method( or (*Type).Method(
        for my $alias (@aliases) {
            $count += () = $content =~ /\b\Q$alias\E\.\Q$recv\E\s*\{[^}]*\}\.\Q$name\E\s*\(/g;
            $count += () = $content =~ /\b\Q$alias\E\.\Q$recv\E\s*\([^)]*\)\.\Q$name\E\s*\(/g;
        }
        # receiver var typed: common patterns insufficient; use .Method( only when same package or import suggests type
        if ($meta->{pkgpath} && $meta->{pkgpath} eq $pp) {
            $count += () = $content =~ /\.\Q$name\E\s*\(/g;
        } elsif (grep { $_ ne (split m{/}, $pp)[-1] } @aliases) {
            # imported package — count qualified and unqualified selector on known vars is hard; use .Method(
            $count += () = $content =~ /\.\Q$name\E\s*\(/g;
        }

        if ($count > 0) {
            $total += $count;
            $caller_files{$f} = 1;
        }
    }
    # Don't replace with worse count; keep original if refinement is zero
}

# Sort and output top 40
my @sorted = sort { ($call_sites{$b} // 0) <=> ($call_sites{$a} // 0) } keys %defs;

print "TOP_SYMBOLS\n";
my $n = 0;
for my $id (@sorted) {
    last if ++$n > 50;
    my $d = $defs{$id};
    my $qual = $d->{pkgpath};
    $qual .= ".$d->{recv}" if $d->{recv} ne '';
    $qual .= "::$d->{name}";
    my $cs = $call_sites{$id} // 0;
    my $cf = scalar keys %{$callers{$id} // {}};
    printf "%4d sites | %3d caller-files | %s | %s:%d\n", $cs, $cf, $qual, $d->{file}, $d->{line};
}

# Method name collision report
print "\nMETHOD_NAME_COLLISIONS\n";
my %by_name;
for (values %defs) {
    push @{$by_name{$_->{name}}}, $_ if $_->{recv} ne '';
}
for my $name (sort { scalar(@{$by_name{$b}}) <=> scalar(@{$by_name{$a}}) } keys %by_name) {
    next unless @{$by_name{$name}} > 5;
    print "$name: " . scalar(@{$by_name{$name}}) . " methods\n";
}

