# within files that don't use that type. Re-count methods more carefully using receiver-qualified patterns where possible.

# Re-run method counting with package context for exported methods on named types
for my $id (keys %defs) {
    my $d = $defs{$id};
    next unless $d->{recv} ne '';

    my $name = $d->{name};
    my $pp = $d->{pkgpath};
    my $recv = $d->{recv};

    # Only re-count if there are competing methods with same name in internal
    my $competitors = 0;
    for (values %defs) {
        $competitors++ if $_->{name} eq $name && $_->{recv} ne '';
    }
    next if $competitors <= 3; # skip refinement for low ambiguity

    my $total = 0;
    my %caller_files;
    for my $f (keys %files) {
        my $meta = $files{$f};
        my $content = strip_comments($meta->{content});
        my @aliases = resolve_aliases($meta, $pp);
        my $count = 0;

        # Type-based: alias.RecvVar.Method( or &Type{}.Method( or (*Type).Method(
        for my $alias (@aliases) {
            $count += () = $content =~ /\b\Q$alias\E\.\Q$recv\E\s*\{[^}]*\}\.\Q$name\E\s*\(/g;
