print "TOP_SYMBOLS\n";
my $n = 0;
for my $id (@sorted) {
    last if ++$n > 50;
    my $d = $defs{$id};
    my $qual = $d->{pkgpath};
    $qual .= ".$d->{recv}" if $d->{recv} ne '';
    $qual .= "::$d->{name}";
    my $cs = $call_sites{$id} // 0;
    my $cf = scalar keys %{$callers{$id} // {}};
