#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $root = '/bench/repo';
my $module = 'github.com/usememos/memos';

my %defs;   # id => def
my %files;  # path => meta

sub rel_pkgpath {
    my ($f) = @_;
    return undef unless $f =~ m{/internal/};
    (my $pp = $f) =~ s{^\Q$root\E/}{};
    $pp =~ s{/[^/]+$}{};
    return $pp;
}

sub read_file {
    my ($f) = @_;
    open my $fh, '<', $f or return '';
    local $/; my $c = <$fh>; close $fh;
    return $c;
}

sub strip_comments {
    my ($c) = @_;
    $c =~ s{//[^\n]*}{}g;
    $c =~ s{/\*.*?\*/}{}gs;
    return $c;
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    while ($content =~ /^\s*import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg) {
        my $block = defined $1 ? $1 : qq{"$2"};
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $path =~ s{^\Q$module\E/}{};
            $alias //= ($path =~ m{/([^/]+)$})[0];
            $imports{$alias} = $path;
        }
    }
    return %imports;
}

find({
    wanted => sub {
        return unless /\.go$/;
        my $f = $File::Find::name;
        my $raw = read_file($f);
        my ($pkg) = $raw =~ /^package\s+(\w+)/m or return;
        my $pp = rel_pkgpath($f);
        my %imports = parse_imports($raw);
        $files{$f} = {
            pkg => $pkg, pkgpath => $pp, imports => \%imports,
            raw => $raw, content => strip_comments($raw),
        };

        return unless defined $pp;
        my $line = 0;
        for my $ln (split /\n/, $raw) {
            $line++;
            if ($ln =~ /^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
                my ($rs, $name) = ($1, $2);
                $rs =~ s/^\*//; $rs =~ s/^\w+\s+//; $rs =~ s/\s+//g;
                my $id = "$pp\x00$rs\x00$name";
                $defs{$id} = { pkgpath=>$pp, pkg=>$pkg, recv=>$rs, name=>$name,
                    file=>$f, line=>$line, exported=>($name=~/^[A-Z]/) };
            } elsif ($ln =~ /^func\s+(\w+)\s*\(/) {
                my $name = $1;
                my $id = "$pp\x00\x00$name";
                $defs{$id} = { pkgpath=>$pp, pkg=>$pkg, recv=>'', name=>$name,
                    file=>$f, line=>$line, exported=>($name=~/^[A-Z]/) };
            }
        }
    },
    no_chdir => 1,
}, $root);

sub aliases_for {
    my ($meta, $target_pp) = @_;
    my $leaf = (split m{/}, $target_pp)[-1];
    my %a = ($leaf => 1);
    for my $al (keys %{$meta->{imports}}) {
        $a{$al} = 1 if $meta->{imports}{$al} eq $target_pp;
    }
    return keys %a;
}

my (%sites, %caller_files);

for my $id (keys %defs) {
    my $d = $defs{$id};
    my ($pp, $recv, $name) = ($d->{pkgpath}, $d->{recv}, $d->{name});

    for my $f (keys %files) {
        my $m = $files{$f};
        my $c = $m->{content};
        my @pats;

        if ($recv eq '') {
            # Package-level function
            if (defined $m->{pkgpath} && $m->{pkgpath} eq $pp) {
                push @pats, qr/(?<![.\w])\Q$name\E\s*\(/;
            }
            if ($d->{exported}) {
                for my $al (aliases_for($m, $pp)) {
                    push @pats, qr/\b\Q$al\E\.\Q$name\E\s*\(/;
                }
            }
        } else {
            # Method: same-package unqualified selector calls
            if (defined $m->{pkgpath} && $m->{pkgpath} eq $pp) {
                push @pats, qr/\.\Q$name\E\s*\(/;
            }
            # Cross-package: only if exported method and package imported
            elsif ($d->{exported}) {
                my @als = aliases_for($m, $pp);
                next unless @als > 1 || ($als[0] && $m->{imports}{$als[0]});
                # For cross-package, count .Method( when package is imported (may include other types' methods)
                push @pats, qr/\.\Q$name\E\s*\(/;
            }
        }

        my $n = 0;
        for my $p (@pats) {
            my $pos = 0;
            while ($c =~ /$p/g) {
                # Exclude definition line pattern "func (r *renderer) Render("
                my $start = $-[0];
                my $before = substr($c, max(0,$start-20), min(20,$start));
                next if $before =~ /func\s*\([^)]*\)\s*$/;
                $n++;
            }
        }
        if ($n > 0) {
            $sites{$id} += $n;
            $caller_files{$id}{$f}++;
        }
    }
}

sub max { $_[0] > $_[1] ? $_[0] : $_[1] }
sub min { $_[0] < $_[1] ? $_[0] : $_[1] }

# Exclude init from ranking (compiler/runtime invoked)
my @ranked = grep {
    my $d = $defs{$_};
    $d->{name} ne 'init'
} sort { ($sites{$b}//0) <=> ($sites{$a}//0) } keys %defs;

print "=== TOP 60 (call sites, caller-files) ===\n";
for my $i (0..59) {
    last unless $ranked[$i];
    my $id = $ranked[$i];
    my $d = $defs{$id};
    my $q = $d->{pkgpath};
    $q .= ".$d->{recv}" if $d->{recv} ne '';
    $q .= ".$d->{name}";
    printf "%4d | %3d files | %s | %s:%d\n",
        $sites{$id}//0, scalar keys %{$caller_files{$id}//{}},
        $q, $d->{file}, $d->{line};
}

# Detailed breakdown for top 5
print "\n=== TOP 5 BREAKDOWN ===\n";
for my $i (0..4) {
    last unless $ranked[$i];
    my $id = $ranked[$i];
    my $d = $defs{$id};
    print "\n--- $d->{pkgpath}";
    print ".$d->{recv}" if $d->{recv};
    print ".$d->{name} ($sites{$id} sites) ---\n";
    for my $f (sort { $caller_files{$id}{$b} <=> $caller_files{$id}{$a} } keys %{$caller_files{$id}}) {
        my $short = $f; $short =~ s{^\Q$root\E/}{};
        printf "  %3d  %s\n", $caller_files{$id}{$f}, $short;
    }
}

# Competing symbols near top
print "\n=== RUNNERS WITHIN 80% OF #1 ===\n";
my $top = $sites{$ranked[0]} // 0;
for my $id (@ranked[0..19]) {
    last unless defined $id;
    my $s = $sites{$id} // 0;
    next if $top > 0 && $s < $top * 0.8;
    my $d = $defs{$id};
    my $q = "$d->{pkgpath}" . ($d->{recv} ? ".$d->{recv}" : "") . ".$d->{name}";
    printf "%4d | %s\n", $s, $q;
}

