#!/usr/bin/perl
use strict;
use warnings;

my $root = '/bench/repo';
my @files = split /\n/, `find '$root' -name '*.go' -type f`;
chomp @files;

# Find distinct caller functions containing CompileToStatement calls
my %callers;
my $current = '(toplevel)';

for my $f (@files) {
    open my $fh, '<', $f or next;
    my $line = 0;
    $current = '(toplevel)';
    while (<$fh>) {
        $line++;
        if (/^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) {
            $current = "$1";
        }
        if (/\bCompileToStatement\s*\(/ && !/^func\s+.*CompileToStatement/) {
            my $short = $f; $short =~ s{^\Q$root\E/}{};
            $callers{"$short:$current"}++;
        }
    }
    close $fh;
}

print "Distinct caller functions: ", scalar(keys %callers), "\n";
print "Total call sites: ", (eval { join '+', map { $callers{$_} } keys %callers } || 0), "\n";
my $total = 0; $total += $_ for values %callers;
print "Total call sites (sum): $total\n\n";
for my $k (sort { $callers{$b} <=> $callers{$a} } keys %callers) {
    printf "  %2d  %s\n", $callers{$k}, $k;
}

# Same for addArg
print "\n=== addArg ===\n";
%callers = (); $total = 0;
for my $f (@files) {
    open my $fh, '<', $f or next;
    $current = '(toplevel)';
    while (<$fh>) {
        if (/^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) { $current = "$1"; }
        if (/\.addArg\s*\(/) {
            my $short = $f; $short =~ s{^\Q$root\E/}{};
            $callers{"$short:$current"}++;
        }
    }
    close $fh;
}
$total = 0; $total += $_ for values %callers;
print "Distinct callers: ", scalar(keys %callers), ", sites: $total\n";

# NewEngine
print "\n=== NewEngine ===\n";
%callers = (); $total = 0;
for my $f (@files) {
    open my $fh, '<', $f or next;
    $current = '(toplevel)';
    while (<$fh>) {
        if (/^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) { $current = "$1"; }
        if (/(?<![.\w])NewEngine\s*\(/ && !/^func\s+NewEngine/) {
            my $short = $f; $short =~ s{^\Q$root\E/}{};
            $callers{"$short:$current"}++;
        }
    }
    close $fh;
}
$total = 0; $total += $_ for values %callers;
print "Distinct callers: ", scalar(keys %callers), ", sites: $total\n";

